EOF
cat > .gitignore <<'EOF'
/target
/executable
/executable.ref
*.zip
!assets/*.zip
EOF
mkdir -p src
cat > src/errors.rs <<'EOF'
use std::fmt;
use std::io;

/// Errors that can be reported by the archive layer.  The `Debug`
/// representation is intentionally kept close to that of common ZIP
/// libraries, as it is shown in some panic messages.
#[derive(Debug)]
pub enum ZipError {
    InvalidArchive(String),
    UnsupportedArchive(String),
    InvalidPassword,
    Io(io::Error),
}

impl fmt::Display for ZipError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ZipError::InvalidArchive(msg) => write!(f, "invalid Zip archive: {}", msg),
            ZipError::UnsupportedArchive(msg) => write!(f, "unsupported Zip archive: {}", msg),
            ZipError::InvalidPassword => write!(f, "invalid password for file in archive"),
            ZipError::Io(err) => write!(f, "{}", err),
        }
    }
}

impl std::error::Error for ZipError {}

impl From<io::Error> for ZipError {
    fn from(err: io::Error) -> Self {
        ZipError::Io(err)
    }
}

/// Top-level application error.  Its `Display` implementation defines the
/// user-facing error strings printed on stderr.
#[derive(Debug)]
pub enum AppError {
    CliArgument(String),
    InvalidZipFile(String),
    FileNumberNotFound(usize),
    Io(io::Error),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            // Note: the string is formatted with `{:?}`, i.e. quoted and
            // escaped, matching the reference behaviour.
            AppError::CliArgument(msg) => write!(f, "CLI argument error - {:?}", msg),
            AppError::InvalidZipFile(msg) => write!(f, "Invalid zip file error - {}", msg),
            AppError::FileNumberNotFound(n) => {
                write!(f, "File number not found within archive error - '{}'", n)
            }
            AppError::Io(err) => write!(f, "standard I/O error - {}", err),
        }
    }
}

impl std::error::Error for AppError {}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        AppError::Io(err)
    }
}

impl From<ZipError> for AppError {
    fn from(err: ZipError) -> Self {
        AppError::InvalidZipFile(err.to_string())
    }
}

pub type AppResult<T> = Result<T, AppError>;

pub fn cli_error<T>(msg: impl Into<String>) -> AppResult<T> {
    Err(AppError::CliArgument(msg.into()))
}
EOF
"}

