//! Self-contained implementations of the cryptographic primitives needed
//! to test ZIP passwords: CRC-32, the legacy ZipCrypto stream cipher,
//! SHA-1, HMAC-SHA1 / PBKDF2 and AES (encryption direction, used for
//! WinZIP AES CTR mode).
use std::sync::OnceLock;

// ---------------------------------------------------------------- CRC-32

pub fn crc32_table() -> &'static [u32; 256] {
    static TABLE: OnceLock<[u32; 256]> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut table = [0u32; 256];
        for (i, entry) in table.iter_mut().enumerate() {
            let mut c = i as u32;
            for _ in 0..8 {
                c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
            }
            *entry = c;
        }
        table
    })
}

/// Raw (non-inverted) CRC step used by the ZipCrypto key schedule.
#[inline]
pub fn crc32_update_raw(crc: u32, byte: u8) -> u32 {
    let table = crc32_table();
    (crc >> 8) ^ table[((crc ^ byte as u32) & 0xff) as usize]
}

#[derive(Clone)]
pub struct Crc32 {
    value: u32,
}

impl Crc32 {
    pub fn new() -> Self {
        Crc32 { value: 0xFFFF_FFFF }
    }
    pub fn update(&mut self, data: &[u8]) {
        let table = crc32_table();
        let mut c = self.value;
        for &b in data {
            c = (c >> 8) ^ table[((c ^ b as u32) & 0xff) as usize];
        }
        self.value = c;
    }
    pub fn finish(&self) -> u32 {
        !self.value
    }
}

pub fn crc32(data: &[u8]) -> u32 {
    let mut h = Crc32::new();
    h.update(data);
    h.finish()
}

// ------------------------------------------------------------- ZipCrypto

pub struct ZipCrypto {
    key0: u32,
    key1: u32,
    key2: u32,
}

impl ZipCrypto {
    pub fn new(password: &[u8]) -> Self {
        let mut crypto = ZipCrypto {
            key0: 0x1234_5678,
            key1: 0x2345_6789,
            key2: 0x3456_7890,
        };
        for &b in password {
            crypto.update_keys(b);
        }
        crypto
    }

    #[inline]
    fn update_keys(&mut self, byte: u8) {
        self.key0 = crc32_update_raw(self.key0, byte);
        self.key1 = (self.key1.wrapping_add(self.key0 & 0xff))
            .wrapping_mul(134_775_813)
            .wrapping_add(1);
        self.key2 = crc32_update_raw(self.key2, (self.key1 >> 24) as u8);
    }

    #[inline]
    fn decrypt_byte(&self) -> u8 {
        let temp = self.key2 | 2;
        (((temp.wrapping_mul(temp ^ 1)) >> 8) & 0xff) as u8
    }

    /// Decrypt `data` in place in the internal state, returning plaintext.
    pub fn decrypt(&mut self, data: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(data.len());
        for &c in data {
            let p = c ^ self.decrypt_byte();
            self.update_keys(p);
            out.push(p);
        }
        out
    }
}

// ------------------------------------------------------------------ SHA-1

#[derive(Clone)]
pub struct Sha1 {
    state: [u32; 5],
    length: u64,
    buffer: [u8; 64],
    buffer_len: usize,
}

impl Sha1 {
    pub fn new() -> Self {
        Sha1 {
            state: [0x6745_2301, 0xEFCD_AB89, 0x98BA_DCFE, 0x1032_5476, 0xC3D2_E1F0],
            length: 0,
            buffer: [0; 64],
            buffer_len: 0,
        }
    }

    fn process_block(state: &mut [u32; 5], block: &[u8]) {
        debug_assert_eq!(block.len(), 64);
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                block[i * 4],
                block[i * 4 + 1],
                block[i * 4 + 2],
                block[i * 4 + 3],
            ]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (state[0], state[1], state[2], state[3], state[4]);
        for i in 0..80 {
            let (f, k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A82_7999u32),
                20..=39 => (b ^ c ^ d, 0x6ED9_EBA1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1B_BCDC),
                _ => (b ^ c ^ d, 0xCA62_C1D6),
            };
            let tmp = a
                .rotate_left(5)
                .wrapping_add(f)
                .wrapping_add(e)
                .wrapping_add(k)
                .wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = tmp;
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
        state[4] = state[4].wrapping_add(e);
    }

    pub fn update(&mut self, mut data: &[u8]) {
        self.length = self.length.wrapping_add(data.len() as u64);
        if self.buffer_len > 0 {
            let take = std::cmp::min(64 - self.buffer_len, data.len());
            self.buffer[self.buffer_len..self.buffer_len + take].copy_from_slice(&data[..take]);
            self.buffer_len += take;
            data = &data[take..];
            if self.buffer_len == 64 {
                let block = self.buffer;
                Self::process_block(&mut self.state, &block);
                self.buffer_len = 0;
            }
        }
        while data.len() >= 64 {
            Self::process_block(&mut self.state, &data[..64]);
            data = &data[64..];
        }
        if !data.is_empty() {
            self.buffer[..data.len()].copy_from_slice(data);
            self.buffer_len = data.len();
        }
    }

    pub fn finalize(mut self) -> [u8; 20] {
        let bit_length = self.length.wrapping_mul(8);
        self.update(&[0x80]);
        while self.buffer_len != 56 {
            // `update` bumps self.length, but padding must not count towards
            // the message length we already captured, and buffer_len drives
            // this loop correctly.
            self.length = self.length.wrapping_sub(1);
            self.update(&[0x00]);
        }
        // Append length without going through update's bookkeeping.
        let len_bytes = bit_length.to_be_bytes();
        for &b in &len_bytes {
            self.buffer[self.buffer_len] = b;
            self.buffer_len += 1;
            if self.buffer_len == 64 {
                let block = self.buffer;
                Self::process_block(&mut self.state, &block);
                self.buffer_len = 0;
            }
        }
        let mut out = [0u8; 20];
        for (i, word) in self.state.iter().enumerate() {
            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
        }
        out
    }
}

pub fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h = Sha1::new();
    h.update(data);
    h.finalize()
}

// ----------------------------------------------------------- HMAC / PBKDF2

#[derive(Clone)]
struct HmacSha1 {
    inner: Sha1,
    outer: Sha1,
}

impl HmacSha1 {
    fn new(key: &[u8]) -> Self {
        let mut key_block = [0u8; 64];
        if key.len() > 64 {
            let hashed = sha1(key);
            key_block[..20].copy_from_slice(&hashed);
        } else {
            key_block[..key.len()].copy_from_slice(key);
        }
        let mut inner_pad = [0u8; 64];
        let mut outer_pad = [0u8; 64];
        for i in 0..64 {
            inner_pad[i] = key_block[i] ^ 0x36;
            outer_pad[i] = key_block[i] ^ 0x5c;
        }
        let mut inner = Sha1::new();
        inner.update(&inner_pad);
        let mut outer = Sha1::new();
        outer.update(&outer_pad);
        HmacSha1 { inner, outer }
    }

    fn compute(&self, data: &[u8]) -> [u8; 20] {
