const RCON: [u8; 10] = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36];

pub struct Aes {
    round_keys: Vec<[u8; 16]>,
}

impl Aes {
    pub fn new(key: &[u8]) -> Self {
        assert!(matches!(key.len(), 16 | 24 | 32), "invalid AES key length");
        let nk = key.len() / 4;
        let nr = nk + 6;
        let mut words: Vec<[u8; 4]> = Vec::with_capacity(4 * (nr + 1));
        for i in 0..nk {
            words.push([key[i * 4], key[i * 4 + 1], key[i * 4 + 2], key[i * 4 + 3]]);
        }
        for i in nk..(4 * (nr + 1)) {
            let mut temp = words[i - 1];
            if i % nk == 0 {
                temp = [
                    SBOX[temp[1] as usize] ^ RCON[i / nk - 1],
                    SBOX[temp[2] as usize],
                    SBOX[temp[3] as usize],
                    SBOX[temp[0] as usize],
                ];
            } else if nk > 6 && i % nk == 4 {
                temp = [
                    SBOX[temp[0] as usize],
                    SBOX[temp[1] as usize],
                    SBOX[temp[2] as usize],
                    SBOX[temp[3] as usize],
                ];
            }
            let prev = words[i - nk];
            words.push([
                prev[0] ^ temp[0],
                prev[1] ^ temp[1],
                prev[2] ^ temp[2],
                prev[3] ^ temp[3],
            ]);
        }
        let mut round_keys = Vec::with_capacity(nr + 1);
        for round in 0..=nr {
            let mut rk = [0u8; 16];
            for col in 0..4 {
                rk[col * 4..col * 4 + 4].copy_from_slice(&words[round * 4 + col]);
            }
            round_keys.push(rk);
        }
        Aes { round_keys }
    }

    pub fn encrypt_block(&self, block: &[u8; 16]) -> [u8; 16] {
        let mut state = *block;
        Self::add_round_key(&mut state, &self.round_keys[0]);
        let rounds = self.round_keys.len() - 1;
        for round in 1..rounds {
            Self::sub_bytes(&mut state);
            Self::shift_rows(&mut state);
            Self::mix_columns(&mut state);
            Self::add_round_key(&mut state, &self.round_keys[round]);
        }
        Self::sub_bytes(&mut state);
        Self::shift_rows(&mut state);
        Self::add_round_key(&mut state, &self.round_keys[rounds]);
        state
    }

    fn add_round_key(state: &mut [u8; 16], round_key: &[u8; 16]) {
        for i in 0..16 {
            state[i] ^= round_key[i];
        }
    }

    fn sub_bytes(state: &mut [u8; 16]) {
        for b in state.iter_mut() {
            *b = SBOX[*b as usize];
        }
    }

    fn shift_rows(state: &mut [u8; 16]) {
        // State is column-major: state[row + 4*col].
        let old = *state;
        for row in 0..4 {
            for col in 0..4 {
                state[row + 4 * col] = old[row + 4 * ((col + row) % 4)];
            }
        }
    }

    fn mix_columns(state: &mut [u8; 16]) {
        fn xtime(x: u8) -> u8 {
            (x << 1) ^ if x & 0x80 != 0 { 0x1b } else { 0x00 }
        }
        for col in 0..4 {
            let i = col * 4;
            let (a, b, c, d) = (state[i], state[i + 1], state[i + 2], state[i + 3]);
            state[i] = xtime(a) ^ (xtime(b) ^ b) ^ c ^ d;
            state[i + 1] = a ^ xtime(b) ^ (xtime(c) ^ c) ^ d;
            state[i + 2] = a ^ b ^ xtime(c) ^ (xtime(d) ^ d);
            state[i + 3] = (xtime(a) ^ a) ^ b ^ c ^ xtime(d);
        }
    }
}

/// WinZIP AES CTR mode encryption/decryption (the operation is symmetric).
/// The counter is a little-endian 128-bit integer starting at 1.
pub fn aes_ctr_crypt(key: &[u8], data: &[u8]) -> Vec<u8> {
    let aes = Aes::new(key);
    let mut out = Vec::with_capacity(data.len());
    let mut counter: u128 = 1;
    for chunk in data.chunks(16) {
        let counter_block = counter.to_le_bytes();
        let keystream = aes.encrypt_block(&counter_block);
        for (i, &b) in chunk.iter().enumerate() {
            out.push(b ^ keystream[i]);
        }
        counter = counter.wrapping_add(1);
    }
    out
}

