        let mut u = hmac.compute_two(salt, &block_index.to_be_bytes());
        let mut t = u;
        for _ in 1..iterations {
            u = hmac.compute(&u);
            for i in 0..20 {
                t[i] ^= u[i];
            }
        }
        let take = std::cmp::min(20, out_len - derived.len());
        derived.extend_from_slice(&t[..take]);
        block_index += 1;
    }
    derived
