//! Brute-force password generation.
//!
//! Passwords are generated in lexicographic order with respect to the
//! (sorted) generation charset: first all passwords of the minimum
//! length, then the next length, and so on.  Within one length the
//! last character cycles fastest.

pub struct PasswordGenerator {
    charset: Vec<char>,
    max_len: usize,
    /// Indices into `charset` for the current password, or `None` when
    /// the search space is exhausted.
    current: Option<Vec<usize>>,
}

impl PasswordGenerator {
    pub fn new(
        charset: Vec<char>,
        min_len: usize,
        max_len: usize,
        starting_password: Option<&str>,
    ) -> Self {
        let current = match starting_password {
            Some(start) => {
                let indices: Vec<usize> = start
                    .chars()
                    .map(|ch| {
                        charset
                            .iter()
                            .position(|&c| c == ch)
                            .expect("starting password validated beforehand")
                    })
                    .collect();
                Some(indices)
            }
            None => {
                // Touch the first character so that an empty charset is
                // reported here, in the worker thread generating
                // passwords.
                let _first = charset.first().expect("charset non empty");
                Some(vec![0; min_len])
            }
        };
        PasswordGenerator {
            charset,
            max_len,
            current,
        }
    }

    pub fn current_password(&self) -> Option<String> {
        self.current
            .as_ref()
            .map(|indices| indices.iter().map(|&i| self.charset[i]).collect())
    }

    /// Advance to the next password.  Returns `false` when exhausted.
    pub fn advance(&mut self) -> bool {
        let Some(indices) = self.current.as_mut() else {
            return false;
        };
        for pos in (0..indices.len()).rev() {
            if indices[pos] + 1 < self.charset.len() {
                indices[pos] += 1;
                return true;
            }
            indices[pos] = 0;
        }
        // All positions rolled over: grow by one character if allowed.
        if indices.len() < self.max_len {
            let new_len = indices.len() + 1;
            self.current = Some(vec![0; new_len]);
            true
        } else {
            self.current = None;
            false
        }
    }
}
EOF
"}

