    pub fn key_len(&self) -> usize {
        match self.strength {
            1 => 16,
            2 => 24,
            _ => 32,
        }
    }
    pub fn salt_len(&self) -> usize {
        match self.strength {
            1 => 8,
            2 => 12,
            _ => 16,
        }
    }
