//! Optional decoding of BZip2 / XZ / LZMA / Zstd compressed data.
//!
//! There are no pure-Rust crates for these formats available in the
//! build environment, so the system compression libraries (which
//! ship with the base OS image) are used through their C APIs.
//! Each entry point returns `None` on any error, which simply makes
//! the password candidate be rejected.

pub fn decode(input: &[u8], method: u16) -> Option<Vec<u8>> {
    match method {
        12 => decode_bzip2(input),
        95 => decode_xz(input),
        14 => decode_zip_lzma(input),
        93 => decode_zstd(input),
        _ => None,
    }
}

