#[repr(C)]
struct BzStream {
    next_in: *const u8,
    avail_in: u32,
    total_in_hi32: u32,
    total_in_lo32: u32,
    next_out: *mut u8,
    avail_out: u32,
    total_out_hi32: u32,
    total_out_lo32: u32,
    state: *mut core::ffi::c_void,
    bzalloc: *mut core::ffi::c_void,
    bzfree: *mut core::ffi::c_void,
    opaque: *mut core::ffi::c_void,
}

