    fn BZ2_bzDecompressInit(strm: *mut BzStream, verbosity: i32, small: i32) -> i32;
    fn BZ2_bzDecompress(strm: *mut BzStream) -> i32;
    fn BZ2_bzDecompressEnd(strm: *mut BzStream) -> i32;
}

fn decode_bzip2(input: &[u8]) -> Option<Vec<u8>> {
    unsafe {
        let mut stream: BzStream = std::mem::zeroed();
        if BZ2_bzDecompressInit(&mut stream, 0, 0) != 0 {
            return None;
        }
        let mut out = Vec::new();
        let mut in_pos = 0usize;
        let result = loop {
            let chunk = &input[in_pos..];
            stream.next_in = chunk.as_ptr();
            stream.avail_in = chunk.len().min(u32::MAX as usize) as u32;
            let consumed_before = stream.avail_in;
            let spare = out.capacity() - out.len();
            if spare < 8192 {
                out.reserve(8192);
            }
            let out_start = out.len();
            let capacity = out.capacity();
            stream.next_out = out.as_mut_ptr().add(out_start);
            stream.avail_out = (capacity - out_start) as u32;
            let avail_before = stream.avail_out;
            let rc = BZ2_bzDecompress(&mut stream);
            let produced = (avail_before - stream.avail_out) as usize;
            out.set_len(out_start + produced);
            in_pos += (consumed_before - stream.avail_in) as usize;
            if rc == 1 {
                break Some(out);
            } else if rc != 0 {
                break None;
            }
            if produced == 0 && in_pos >= input.len() {
                break None;
            }
            // Guard against unbounded output from corrupt data.
            if out.len() > 1 << 31 {
                break None;
            }
        };
        BZ2_bzDecompressEnd(&mut stream);
        result
    }
}

