fn run_lzma(stream: &mut LzmaStream, input: &[u8]) -> Option<Vec<u8>> {
    unsafe {
        let mut out = Vec::new();
        stream.next_in = input.as_ptr();
        stream.avail_in = input.len();
        loop {
            if out.capacity() - out.len() < 8192 {
                out.reserve(8192);
            }
            let out_start = out.len();
            let capacity = out.capacity();
            stream.next_out = out.as_mut_ptr().add(out_start);
            stream.avail_out = capacity - out_start;
            let rc = lzma_code(stream, 1); // LZMA_FINISH
            let produced = capacity - out_start - stream.avail_out;
            out.set_len(out_start + produced);
            if rc == 1 {
                // LZMA_STREAM_END
                lzma_end(stream);
                return Some(out);
            }
            if rc != 0 {
                lzma_end(stream);
                return None;
            }
            if produced == 0 && stream.avail_in == 0 {
                lzma_end(stream);
                return None;
            }
            if out.len() > 1 << 31 {
                lzma_end(stream);
                return None;
            }
        }
    }
}

fn decode_xz(input: &[u8]) -> Option<Vec<u8>> {
    unsafe {
        let mut stream = lzma_stream_new();
        if lzma_auto_decoder(&mut stream, u64::MAX, 0) != 0 {
            return None;
        }
        run_lzma(&mut stream, input)
    }
}

fn decode_zip_lzma(input: &[u8]) -> Option<Vec<u8>> {
    // ZIP LZMA (method 14) layout: 2 bytes version of the LZMA SDK
    // encoding, 2 bytes size of the LZMA properties, then the
    // properties themselves, then a raw LZMA1 stream.  The classic
    // ".lzma alone" format is: 5 property bytes, 8 bytes
    // uncompressed size, then the same raw stream.  Synthesise an
    // alone header with an unknown size and let liblzma decode it.
    if input.len() < 4 {
        return None;
    }
    let props_size = u16::from_le_bytes([input[2], input[3]]) as usize;
    if props_size != 5 || input.len() < 4 + props_size {
        return None;
    }
    let props = &input[4..4 + props_size];
    let mut alone = Vec::with_capacity(13 + input.len());
    alone.extend_from_slice(props);
    alone.extend_from_slice(&u64::MAX.to_le_bytes());
    alone.extend_from_slice(&input[4 + props_size..]);
    unsafe {
        let mut stream = lzma_stream_new();
        if lzma_alone_decoder(&mut stream, u64::MAX) != 0 {
            return None;
        }
        run_lzma(&mut stream, &alone)
    }
}

