//! Validation for compression methods other than Stored / Deflate.
//! These are only reached for the (rare) candidate passwords that
//! pass the fast encryption-header check.

use crate::crypto::{crc32, Crc32};
use std::io::Read;

pub fn validate(input: &[u8], method: u16, expected_len: u64, expected_crc: Option<u32>) -> bool {
    match method {
        // Deflate64 streams are mostly Deflate streams; many small
        // files encoded as Deflate64 decode fine with a plain
        // Deflate decoder, so try that before giving up.
        9 => validate_deflate(input, expected_len, expected_crc),
        // BZip2, LZMA, Zstd, XZ and PPMd are supported through
        // external/system facilities where available.
        12 | 14 | 93 | 95 | 98 => validate_external(input, method, expected_len, expected_crc),
        _ => false,
    }
}

fn validate_deflate(input: &[u8], expected_len: u64, expected_crc: Option<u32>) -> bool {
    let mut decoder = flate2::read::DeflateDecoder::new(input);
    let mut buffer = [0u8; 8192];
    let mut count: u64 = 0;
    let mut crc = Crc32::new();
    loop {
        match decoder.read(&mut buffer) {
            Ok(0) => break,
            Ok(n) => {
                count += n as u64;
                if count > expected_len {
                    return false;
                }
                if expected_crc.is_some() {
                    crc.update(&buffer[..n]);
                }
            }
            Err(_) => return false,
        }
    }
    count == expected_len && expected_crc.map_or(true, |c| crc.finish() == c)
}

fn check_output(output: &[u8], expected_len: u64, expected_crc: Option<u32>) -> bool {
    output.len() as u64 == expected_len
        && expected_crc.map_or(true, |c| crc32(output) == c)
}

fn validate_external(input: &[u8], method: u16, expected_len: u64, expected_crc: Option<u32>) -> bool {
    // These decoders are wired up in `external` below using system
    // libraries when possible.  If decoding fails for any reason the
    // candidate is rejected.
    match crate::external_codec::decode(input, method) {
        Some(output) => check_output(&output, expected_len, expected_crc),
        None => false,
    }
}
