        avail_in: 0,
        total_in: 0,
        next_out: std::ptr::null_mut(),
        avail_out: 0,
        total_out: 0,
        allocator: std::ptr::null(),
        internal: std::ptr::null_mut(),
        reserved_ptr1: std::ptr::null_mut(),
        reserved_ptr2: std::ptr::null_mut(),
        reserved_ptr3: std::ptr::null_mut(),
        reserved_ptr4: std::ptr::null_mut(),
