fn run_lzma(stream: &mut LzmaStream, input: &[u8]) -> Option<Vec<u8>> {
    unsafe {
        let mut out = Vec::new();
        stream.next_in = input.as_ptr();
        stream.avail_in = input.len();
        loop {
            if out.capacity() - out.len() < 8192 {
                out.reserve(8192);
            }
            let out_start = out.len();
            let capacity = out.capacity();
            stream.next_out = out.as_mut_ptr().add(out_start);
            stream.avail_out = capacity - out_start;
            let rc = lzma_code(stream, 1); // LZMA_FINISH
            let produced = capacity - out_start - stream.avail_out;
            out.set_len(out_start + produced);
            if rc == 1 {
                // LZMA_STREAM_END
                lzma_end(stream);
                return Some(out);
            }
            if rc != 0 {
                lzma_end(stream);
                return None;
            }
            if produced == 0 && stream.avail_in == 0 {
                lzma_end(stream);
                return None;
            }
            if out.len() > 1 << 31 {
                lzma_end(stream);
                return None;
            }
        }
    }
