#[link(name = "zstd")]
extern "C" {
    fn ZSTD_getFrameContentSize(src: *const core::ffi::c_void, src_size: usize) -> u64;
    fn ZSTD_decompress(
        dst: *mut core::ffi::c_void,
        dst_capacity: usize,
        src: *const core::ffi::c_void,
        src_size: usize,
    ) -> usize;
    fn ZSTD_isError(code: usize) -> u32;
    fn ZSTD_DStreamOutSize() -> usize;
    fn ZSTD_createDStream() -> *mut core::ffi::c_void;
    fn ZSTD_freeDStream(zds: *mut core::ffi::c_void) -> usize;
    fn ZSTD_initDStream_srcSize(zds: *mut core::ffi::c_void, src_size: usize) -> usize;
    fn ZSTD_decompressStream(
        zds: *mut core::ffi::c_void,
        output: *mut ZstdOutBuffer,
        input: *mut ZstdInBuffer,
    ) -> usize;
}

#[repr(C)]
struct ZstdInBuffer {
    src: *const core::ffi::c_void,
    size: usize,
    pos: usize,
}
#[repr(C)]
struct ZstdOutBuffer {
    dst: *mut core::ffi::c_void,
    size: usize,
    pos: usize,
}

fn decode_zstd(input: &[u8]) -> Option<Vec<u8>> {
    unsafe {
        // Fast path when the frame stores its content size.
        let content_size = ZSTD_getFrameContentSize(input.as_ptr() as *const _, input.len());
        if content_size != u64::MAX && content_size != u64::MAX - 1 {
            if content_size > (1u64 << 31) {
                return None;
            }
            let mut out = vec![0u8; content_size as usize];
            let rc = ZSTD_decompress(
                out.as_mut_ptr() as *mut _,
                out.len(),
                input.as_ptr() as *const _,
                input.len(),
            );
            if ZSTD_isError(rc) != 0 || rc != out.len() {
                return None;
            }
            return Some(out);
        }
        // Streaming path.
        let dstream = ZSTD_createDStream();
        if dstream.is_null() {
            return None;
        }
        let mut result = None;
        if ZSTD_isError(ZSTD_initDStream_srcSize(dstream, input.len())) == 0 {
            let mut out = Vec::new();
            let mut in_buf = ZstdInBuffer {
                src: input.as_ptr() as *const _,
                size: input.len(),
                pos: 0,
            };
            let out_chunk = ZSTD_DStreamOutSize();
            loop {
                if out.capacity() - out.len() < out_chunk {
                    out.reserve(out_chunk);
                }
                let start = out.len();
                let capacity = out.capacity();
                let mut out_buf = ZstdOutBuffer {
                    dst: out.as_mut_ptr().add(start) as *mut _,
                    size: capacity - start,
                    pos: 0,
                };
                let rc = ZSTD_decompressStream(dstream, &mut out_buf, &mut in_buf);
                out.set_len(start + out_buf.pos);
                if ZSTD_isError(rc) != 0 {
                    break;
                }
                if rc == 0 {
                    result = Some(out);
                    break;
                }
                if out_buf.pos == 0 && in_buf.pos >= in_buf.size {
                    break;
                }
                if out.len() > 1 << 31 {
                    break;
                }
            }
        }
        ZSTD_freeDStream(dstream);
        result
    }
}
