//! Multi-threaded password searching.

use crate::errors::AppResult;
use crate::password_gen::PasswordGenerator;
use crate::zip_utils::{check_password, open_and_prepare_target, Target};
use std::collections::BTreeSet;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

pub struct SearchConfig {
    pub input_file: PathBuf,
    pub workers: Option<usize>,
    pub password_dictionary: Option<PathBuf>,
    pub charset: BTreeSet<char>,
    pub min_password_len: usize,
    pub max_password_len: usize,
    pub file_number: usize,
    pub starting_password: Option<String>,
}

struct SharedState {
    found: AtomicBool,
    password: Mutex<Option<String>>,
}

impl SharedState {
    fn new() -> Self {
        SharedState {
            found: AtomicBool::new(false),
            password: Mutex::new(None),
        }
    }
    fn set_found(&self, password: String) {
        let mut slot = self.password.lock().unwrap();
        if slot.is_none() {
            *slot = Some(password);
        }
        self.found.store(true, Ordering::Relaxed);
    }
    fn is_found(&self) -> bool {
        self.found.load(Ordering::Relaxed)
    }
}

fn test_candidate(state: &SharedState, target: &Target, password: String) -> bool {
    match check_password(&password, target) {
        Ok(true) => {
            state.set_found(password);
            true
        }
        Ok(false) => false,
        Err(error) => panic!("Unexpected error {:?}", error),
    }
}

/// Determine the default number of workers (physical CPU cores).
pub fn default_workers() -> usize {
    physical_core_count().unwrap_or_else(|| {
        thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    })
}

fn physical_core_count() -> Option<usize> {
    let contents = std::fs::read_to_string("/proc/cpuinfo").ok()?;
    let mut cores = BTreeSet::new();
    let mut physical_id = String::new();
    let mut core_id = String::new();
    let mut seen_any = false;
    for line in contents.lines() {
        if let Some((key, value)) = line.split_once(':') {
            match key.trim() {
                "physical id" => {
                    physical_id = value.trim().to_string();
                    seen_any = true;
                }
                "core id" => {
                    core_id = value.trim().to_string();
                    seen_any = true;
                }
                _ => {}
            }
        }
        if line.trim().is_empty() && seen_any {
            cores.insert((physical_id.clone(), core_id.clone()));
            physical_id.clear();
            core_id.clear();
            seen_any = false;
        }
    }
    if seen_any {
        cores.insert((physical_id, core_id));
    }
    if cores.is_empty() {
        None
    } else {
        Some(cores.len())
    }
}

pub fn find_password(config: &SearchConfig) -> AppResult<Option<String>> {
    let target = open_and_prepare_target(&config.input_file, config.file_number)?;
