fn search_brute_force(
    config: &SearchConfig,
    workers: usize,
    target: &Target,
    state: &Arc<SharedState>,
) {
    let charset: Vec<char> = config.charset.iter().copied().collect();
    let mut handles = Vec::new();
    for index in 0..workers {
        let state = state.clone();
        let target = target.clone();
        let charset = charset.clone();
        let min_len = config.min_password_len;
        let max_len = config.max_password_len;
        let starting = config.starting_password.clone();
        let handle = thread::Builder::new()
            .name(format!("worker-{}", index + 1))
            .spawn(move || {
                let mut generator = PasswordGenerator::new(
                    charset,
                    min_len,
                    max_len,
                    starting.as_deref(),
                );
                // Each worker tests every `workers`-th password,
                // starting at its own offset.
                for _ in 0..index {
                    if !generator.advance() {
                        return;
                    }
                }
                while !state.is_found() {
                    let Some(password) = generator.current_password() else {
                        return;
                    };
                    let mut exhausted = false;
                    for _ in 0..workers {
                        if !generator.advance() {
                            exhausted = true;
                            break;
                        }
                    }
                    if test_candidate(&state, &target, password) {
                        return;
                    }
                    if exhausted {
                        return;
                    }
                }
            })
            .unwrap();
        handles.push(handle);
    }
    for handle in handles {
        let _ = handle.join();
    }
}

fn search_dictionary(
    dictionary: &PathBuf,
    workers: usize,
    target: &Target,
    state: &Arc<SharedState>,
) -> AppResult<()> {
    let file = File::open(dictionary)?;
    let (sender, receiver) = mpsc::sync_channel::<String>(1024);
    let receiver = Arc::new(Mutex::new(receiver));
    let mut handles = Vec::new();
    for index in 0..workers {
        let state = state.clone();
        let target = target.clone();
        let receiver = receiver.clone();
        let handle = thread::Builder::new()
            .name(format!("worker-{}", index + 1))
            .spawn(move || {
                while !state.is_found() {
                    let password = {
                        let guard = receiver.lock().unwrap();
                        match guard.recv() {
                            Ok(password) => password,
                            Err(_) => return,
                        }
                    };
                    if state.is_found() {
                        return;
                    }
                    if test_candidate(&state, &target, password) {
                        return;
                    }
                }
            })
            .unwrap();
        handles.push(handle);
    }
    drop(receiver);

    let reader = BufReader::new(file);
    for line in reader.lines().flatten() {
        if state.is_found() {
            break;
        }
        if sender.send(line).is_err() {
            break;
        }
    }
    drop(sender);
    for handle in handles {
        let _ = handle.join();
    }
    Ok(())
}
