fn decompress(input: &[u8], expected_len: u64) -> Option<Vec<u8>> {
    let mut reader = BitReader::new(input);
    let mut output: Vec<u8> = Vec::new();
    loop {
        let is_final = reader.read_bit()? == 1;
        let block_type = reader.read_bits(2)?;
        match block_type {
            0 => {
                reader.align_byte();
                let header = reader.read_bytes(4)?;
                let len = u16::from_le_bytes([header[0], header[1]]) as usize;
                let nlen = u16::from_le_bytes([header[2], header[3]]);
                if nlen != !(len as u16) {
                    return None;
                }
                if output.len() as u64 + len as u64 > expected_len {
                    return None;
                }
                let stored = reader.read_bytes(len)?;
                output.extend_from_slice(stored);
            }
            1 | 2 => {
                let (lit_table, dist_table) = if block_type == 1 {
                    fixed_tables()?
                } else {
                    dynamic_tables(&mut reader)?
                };
                loop {
                    let symbol = lit_table.decode(&mut reader)?;
                    if symbol < 256 {
                        output.push(symbol as u8);
                        if output.len() as u64 > expected_len {
                            return None;
                        }
                    } else if symbol == 256 {
                        break;
                    } else if symbol > 285 {
                        return None;
                    } else {
                        let length = if symbol == 285 {
                            3 + reader.read_bits(16)? as usize
                        } else {
                            let index = (symbol - 257) as usize;
                            LENGTH_BASE[index]
                                + reader.read_bits(LENGTH_EXTRA[index])? as usize
                        };
                        let dist_symbol = dist_table.decode(&mut reader)? as usize;
                        if dist_symbol >= DIST_BASE.len() {
                            return None;
                        }
                        let distance = DIST_BASE[dist_symbol]
                            + reader.read_bits(DIST_EXTRA[dist_symbol])? as usize;
                        if distance == 0 || distance > output.len() {
                            return None;
                        }
                        if output.len() as u64 + length as u64 > expected_len {
                            return None;
                        }
                        let mut source = output.len() - distance;
                        for _ in 0..length {
                            let byte = output[source];
                            output.push(byte);
                            source += 1;
                        }
                    }
                }
            }
            _ => return None,
        }
        if is_final {
            break;
        }
    }
    Some(output)
}

pub fn validate(input: &[u8], expected_len: u64, expected_crc: Option<u32>) -> bool {
    match decompress(input, expected_len) {
        Some(output) => {
            output.len() as u64 == expected_len
                && expected_crc.map_or(true, |crc| crc32(&output) == crc)
        }
        None => false,
    }
}
