    fn read_bit(&mut self) -> Option<u32> {
        let byte = self.data.get(self.bit_pos / 8)?;
        let bit = (byte >> (self.bit_pos % 8)) & 1;
        self.bit_pos += 1;
        Some(bit as u32)
    }

    fn read_bits(&mut self, count: u32) -> Option<u32> {
        let mut value = 0u32;
        for i in 0..count {
            value |= self.read_bit()? << i;
        }
        Some(value)
    }

    fn align_byte(&mut self) {
        self.bit_pos = (self.bit_pos + 7) / 8 * 8;
    }

    fn read_bytes(&mut self, count: usize) -> Option<&'a [u8]> {
        debug_assert_eq!(self.bit_pos % 8, 0);
        let start = self.bit_pos / 8;
        let bytes = self.data.get(start..start + count)?;
        self.bit_pos += count * 8;
        Some(bytes)
    }
}

struct Huffman {
    // Maps (code length, code) to a symbol; stored per length.
    by_length: Vec<HashMap<u32, u16>>,
    max_length: usize,
}

impl Huffman {
    fn new(lengths: &[u8]) -> Option<Self> {
        let max_length = lengths.iter().copied().max().unwrap_or(0) as usize;
        if max_length > 15 {
            return None;
        }
        let mut counts = [0u32; 16];
        for &len in lengths {
            counts[len as usize] += 1;
        }
        counts[0] = 0;
        let mut next_code = [0u32; 16];
        let mut code = 0u32;
        for len in 1..=15 {
            code = (code + counts[len - 1]) << 1;
            next_code[len] = code;
        }
        let mut by_length: Vec<HashMap<u32, u16>> = vec![HashMap::new(); 16];
        for (symbol, &len) in lengths.iter().enumerate() {
            if len == 0 {
                continue;
            }
            let len = len as usize;
            let assigned = next_code[len];
            if assigned >= (1u32 << len) {
                return None;
            }
            by_length[len].insert(assigned, symbol as u16);
            next_code[len] += 1;
        }
        Some(Huffman {
            by_length,
            max_length,
        })
    }

    fn decode(&self, reader: &mut BitReader) -> Option<u16> {
        if self.max_length == 0 {
            return None;
        }
        let mut code = 0u32;
        for len in 1..=self.max_length {
            code = (code << 1) | reader.read_bit()?;
            if let Some(&symbol) = self.by_length[len].get(&code) {
                return Some(symbol);
            }
        }
        None
    }
}

fn fixed_tables() -> Option<(Huffman, Huffman)> {
    let mut lit_lengths = [0u8; 288];
    lit_lengths[0..144].fill(8);
    lit_lengths[144..256].fill(9);
    lit_lengths[256..280].fill(7);
    lit_lengths[280..288].fill(8);
    let dist_lengths = [5u8; 32];
    Some((
        Huffman::new(&lit_lengths)?,
        Huffman::new(&dist_lengths)?,
    ))
}

fn dynamic_tables(reader: &mut BitReader) -> Option<(Huffman, Huffman)> {
    let hlit = reader.read_bits(5)? as usize + 257;
    let hdist = reader.read_bits(5)? as usize + 1;
    let hclen = reader.read_bits(4)? as usize + 4;
    if hlit > 288 || hdist > 32 {
        return None;
    }
    const ORDER: [usize; 19] = [
        16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15,
    ];
    let mut code_length_lengths = [0u8; 19];
    for i in 0..hclen {
        code_length_lengths[ORDER[i]] = reader.read_bits(3)? as u8;
    }
    let code_length_table = Huffman::new(&code_length_lengths)?;
    let total = hlit + hdist;
    let mut lengths: Vec<u8> = Vec::with_capacity(total);
    while lengths.len() < total {
        let symbol = code_length_table.decode(reader)?;
        match symbol {
            0..=15 => lengths.push(symbol as u8),
            16 => {
                let previous = *lengths.last()?;
                let repeat = reader.read_bits(2)? as usize + 3;
                if lengths.len() + repeat > total {
                    return None;
                }
                lengths.extend(std::iter::repeat(previous).take(repeat));
            }
            17 => {
                let repeat = reader.read_bits(3)? as usize + 3;
                if lengths.len() + repeat > total {
                    return None;
                }
                lengths.extend(std::iter::repeat(0).take(repeat));
            }
            18 => {
                let repeat = reader.read_bits(7)? as usize + 11;
                if lengths.len() + repeat > total {
                    return None;
                }
                lengths.extend(std::iter::repeat(0).take(repeat));
            }
            _ => return None,
        }
    }
    let (lit_lengths, dist_lengths) = lengths.split_at(hlit);
    Some((
        Huffman::new(lit_lengths)?,
        Huffman::new(dist_lengths)?,
    ))
}
