fn parse_timestamp_extra(declared_len: usize, content: &[u8]) -> Result<(), ZipError> {
    if content.is_empty() {
        return invalid("Extended timestamp field is empty");
    }
    let flags = content[0];
    if declared_len != 5 && declared_len != 1 + 4 * (flags.count_ones() as usize) {
        return Err(ZipError::Io(std::io::Error::new(
