fn parse_unicode_extra(
    content: &[u8],
    crc_source: &mut Vec<u8>,
) -> Result<String, ZipError> {
    if content.len() < 5 {
        return Err(unexpected_eof());
    }
    let stored_crc = read_u32(content, 1);
    if crc32(crc_source) != stored_crc {
        return invalid("CRC32 checksum failed on Unicode extra field");
    }
    let text = String::from_utf8(content[5..].to_vec())
        .map_err(|_| ZipError::InvalidArchive("Invalid UTF-8".to_string()))?;
    *crc_source = content[5..].to_vec();
    Ok(text)
