fn truncated_extra_error(id: u16, size: usize, available: &[u8]) -> ZipError {
    match id {
        0x0001 => ZipError::InvalidArchive("ZIP64 extra field truncated".to_string()),
        0x9901 => {
            if size != 7 {
                ZipError::UnsupportedArchive(
                    "AES extra data field has an unsupported length".to_string(),
                )
            } else {
                unexpected_eof()
            }
        }
        0x000a => {
            if size != 32 {
                ZipError::UnsupportedArchive(
                    "NTFS extra field has an unsupported length".to_string(),
                )
            } else {
                unexpected_eof()
            }
        }
        0x5455 => match parse_timestamp_extra(size, available) {
            Ok(()) => unexpected_eof(),
            Err(e) => e,
        },
        0x7075 | 0x6375 => unexpected_eof(),
        _ => ZipError::InvalidArchive("Extra field content truncated".to_string()),
    }
}

fn parse_extra_fields(
    extra: &[u8],
    raw_name: &[u8],
    raw_comment: &[u8],
    name: &mut String,
    uncompressed_size: &mut u64,
    compressed_size: &mut u64,
    header_offset: &mut u64,
    disk_start: u16,
) -> Result<Option<AesMode>, ZipError> {
    let mut aes_mode = None;
    let mut name_crc_source = raw_name.to_vec();
    let mut comment_crc_source = raw_comment.to_vec();
    let mut offset = 0usize;
    while offset < extra.len() {
        if extra.len() - offset < 4 {
            return invalid("Extra field header truncated");
        }
        let id = read_u16(extra, offset);
        let size = read_u16(extra, offset + 2) as usize;
        if size > extra.len() - offset - 4 {
            return Err(truncated_extra_error(id, size, &extra[offset + 4..]));
        }
        let content = &extra[offset + 4..offset + 4 + size];
        match id {
            0x0001 => {
                parse_zip64_extra(
                    content,
                    uncompressed_size,
                    compressed_size,
                    header_offset,
                    disk_start,
                )?;
            }
            0x9901 => {
                if size != 7 {
                    return unsupported("AES extra data field has an unsupported length");
                }
                let version = read_u16(content, 0);
                let vendor = &content[2..4];
                let strength = content[4];
                let actual_method = read_u16(content, 5);
                if vendor != b"AE" {
                    return invalid("Invalid AES vendor");
                }
                if version != 1 && version != 2 {
                    return invalid("Invalid AES vendor version");
                }
                if !(1..=3).contains(&strength) {
                    return invalid("Invalid AES encryption strength");
                }
                aes_mode = Some(AesMode {
                    version,
                    strength,
                    compression_method: actual_method,
                });
            }
            0x7075 => {
                *name = parse_unicode_extra(content, &mut name_crc_source)?;
            }
            0x6375 => {
                let _ = parse_unicode_extra(content, &mut comment_crc_source)?;
            }
            0x5455 => {
                parse_timestamp_extra(size, content)?;
            }
            0x000a => {
                if size != 32 {
                    return unsupported("NTFS extra field has an unsupported length");
                }
                if read_u16(content, 4) != 1 {
                    return unsupported("NTFS extra field has an unsupported attribute tag");
                }
                if read_u16(content, 6) != 24 {
                    return unsupported("NTFS extra field has an unsupported attribute size");
                }
            }
            _ => {}
        }
        offset += 4 + size;
    }
    Ok(aes_mode)
}

